#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Add a Thorny Times banner to the main menu of Discord Times (DiscordTimes.exe).

Usage (Python 3.8+, standard library only):
    python patch_dt.py [DiscordTimes.exe] [--image capsule.png] [--url URL]
                       [--caption TEXT] [--restore]

The original is copied to DiscordTimes.exe.bak first; --restore puts it back.
The machine code block below is generated by tools/build_code.py (needs keystone).
"""
import argparse
import os
import struct
import sys
import zlib
from pathlib import Path

# --- generated by tools/build_code.py: do not edit by hand ---
CODE = bytes.fromhex(
    ""
)
FIX_ABS = [12, 23, 30, 40, 50, 60, 70, 74, 80, 84, 90, 94, 100, 104, 109, 127, 136, 142, 152, 157, 167, 173, 179, 188, 208, 213, 218, 235, 246, 257, 330, 352, 380, 385]
FIX_REL = [1, 17, 119, 203, 228, 268, 274, 289, 314, 345, 368]
ENTRY = {'build_hook': 0, 'draw_hook': 124, 'on_enter': 328, 'on_leave': 350, 'on_press': 358, 'on_click': 373}
LAYOUT = {'WIDGET': 0x400, 'HOVER': 0x480, 'INITED': 0x481, 'IMG_N': 0x484, 'IMG_L': 0x488, 'TW': 0x48c, 'TH': 0x490, 'OPEN': 0x4a0, 'CAPTION': 0x4b0, 'URL': 0x5b0, 'PIX_N': 0x700, 'PIX_L': 0xf283}
PIC_W, PIC_H, PIC_X, PIC_Y = 231, 87, 777, 658
# --- end of generated code ---

HERE = Path(__file__).resolve().parent
IMAGE_BASE = 0x400000
DEFAULT_URL = "https://store.steampowered.com/app/2182610/"
DEFAULT_CAPTION = 'Новая игра от разработчиков "Времён раздора"'
HOOK_BUILD = 0x4D2A27  # BuildMainMenu: call AddChild; ret (6 bytes)
HOOK_DRAW = 0x4C7D24   # DrawMainMenuBackground: call SurfUnlock (5 bytes)
IAT_SHELLEXECUTE = 0xC0B778
IAT_SHOWWINDOW = 0xC0B5E0
EXPECTED_BYTES = [
    (0x4D2A27, "e890ccfaffc3"),
    (0x4C7D24, "e83ff0faff"),
    (0x4797F0, "558bec83c4f8e82d"),
    (0x47F6BC, "558bec83c4f48955"),
    (0x4774A0, "558bec83c4f46689"),
    (0x476374, "558bec83c4f8884d"),
    (0x476EA8, "558bec83c4d0894d"),
    (0x4788EC, "558bec83c4e4894d"),
    (0x478CAC, "558bec83c4e4894d"),
    (0x476D68, "558bec83c4f8803d"),
    (0x481420, "558bec83c4f8884d"),
]
IMPORT_NAMES = [(IAT_SHELLEXECUTE, b"ShellExecuteA"), (IAT_SHOWWINDOW, b"ShowWindow")]
SECTION_NAME = b".banner"
SECTION_FLAGS = 0xE0000060  # code | initialized data | execute | read | write
DYNAMIC_BASE = 0x40
DARK = (20, 13, 8)
GOLD = (255, 209, 107)
MASK = 0xFFFFFFFF
GLYPHS = set(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    "abcdefghijklmnopqrstuvwxyz"
    "1234567890"
    "\\=-+?!,.'\":;()<>/% "
    "АБВГДЕЁЖЗИЙКЛМНОПРСТУФХЦЧШЩЬЫЪЭЮЯ"
    "абвгдеёжзийклмнопрстуфхцчшщьыъэюя"
    "@_"
)
PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"


class PatchError(Exception):
    """A refusal or failed check. The message is Russian / English."""

    def __init__(self, ru, en):
        super(PatchError, self).__init__("%s / %s" % (ru, en))


def align_up(value, alignment):
    return (value + alignment - 1) // alignment * alignment


# ---------------------------------------------------------------- PE file

class Section(object):
    def __init__(self, name, vsize, va, rawsize, rawptr, chars):
        self.name = name
        self.vsize = vsize
        self.va = va
        self.rawsize = rawsize
        self.rawptr = rawptr
        self.chars = chars


class Pe(object):
    """Minimal PE32 reader: just what the patcher needs."""

    def __init__(self, data):
        self.data = data
        if len(data) < 0x40 or data[:2] != b"MZ":
            raise PatchError("Это не EXE-файл (нет заголовка MZ)", "not an EXE file (no MZ header)")
        e_lfanew = struct.unpack_from("<I", data, 0x3C)[0]
        if e_lfanew + 24 > len(data) or data[e_lfanew:e_lfanew + 4] != b"PE\0\0":
            raise PatchError("Нет заголовка PE", "no PE header")
        self.nsec_off = e_lfanew + 6
        machine, nsec, _ts, _pst, _nsym, opt_size, _chars = struct.unpack_from("<HHIIIHH", data, e_lfanew + 4)
        if machine != 0x14C:
            raise PatchError("Не 32-битный x86 (i386)", "not a 32-bit x86 (i386) file")
        opt = e_lfanew + 24
        if opt_size < 96 or opt + opt_size > len(data):
            raise PatchError("Повреждённый optional header", "bad optional header")
        if struct.unpack_from("<H", data, opt)[0] != 0x10B:
            raise PatchError("Не PE32 (magic 0x10b)", "not PE32 (magic 0x10b)")
        image_base = struct.unpack_from("<I", data, opt + 28)[0]
        self.section_align, self.file_align = struct.unpack_from("<II", data, opt + 32)
        self.size_of_image_off = opt + 56
        self.size_of_image = struct.unpack_from("<I", data, opt + 56)[0]
        self.size_of_headers = struct.unpack_from("<I", data, opt + 60)[0]
        self.checksum_off = opt + 64
        dll_chars = struct.unpack_from("<H", data, opt + 70)[0]
        if image_base != IMAGE_BASE:
            raise PatchError("ImageBase 0x%x, нужен 0x400000" % image_base,
                             "ImageBase is 0x%x, expected 0x400000" % image_base)
        if dll_chars & DYNAMIC_BASE:
            raise PatchError("Файл перемещаемый (DYNAMIC_BASE): не поддержано",
                             "file is relocatable (DYNAMIC_BASE): not supported")
        if self.file_align == 0 or self.section_align == 0:
            raise PatchError("Повреждённые выравнивания", "bad alignment fields")
        self.sec_table = opt + opt_size
        if nsec < 1 or self.sec_table + 40 * nsec > self.size_of_headers:
            raise PatchError("Повреждённая таблица секций", "bad section table")
        self.nsec = nsec
        self.sections = []
        for i in range(nsec):
            fields = struct.unpack_from("<8sIIIIIIHHI", data, self.sec_table + 40 * i)
            name, vsize, va, rawsize, rawptr = fields[0], fields[1], fields[2], fields[3], fields[4]
            self.sections.append(Section(name.rstrip(b"\0"), vsize, va, rawsize, rawptr, fields[9]))

    def va_to_off(self, va, n):
        rva = va - IMAGE_BASE
        for s in self.sections:
            avail = min(s.vsize, s.rawsize) if s.vsize else s.rawsize
            if s.va <= rva and rva + n <= s.va + avail:
                return s.rawptr + (rva - s.va)
        raise PatchError("адрес 0x%x нет в данных файла" % va,
                         "address 0x%x is not in the file data" % va)

    def read_va(self, va, n):
        off = self.va_to_off(va, n)
        return self.data[off:off + n]

    def read_cstr_va(self, va, maxlen=64):
        off = self.va_to_off(va, 1)
        end = self.data.find(b"\0", off, off + maxlen + 1)
        if end < 0:
            raise PatchError("строка по адресу 0x%x не закончена" % va,
                             "string at 0x%x is not terminated" % va)
        return self.data[off:end]


def pe_checksum(data, checksum_off):
    """PE image checksum (as imagehlp computes it): 16-bit word sum, carries folded, plus the length."""
    buf = bytearray(data)
    buf[checksum_off:checksum_off + 4] = b"\0\0\0\0"
    n = len(buf)
    even = n - (n & 1)
    total = sum(struct.unpack("<%dH" % (even // 2), bytes(buf[:even])))
    if n & 1:
        total += buf[-1]
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    return (total + n) & MASK


def check_exe(pe):
    """Refuse anything but the known builds (checks 2-6 of the spec)."""
    for s in pe.sections:
        if s.name == SECTION_NAME:
            raise PatchError("секция .banner уже есть: файл пропатчен",
                             "section .banner already exists: the file is already patched")
    for va, hexbytes in EXPECTED_BYTES:
        want = bytes.fromhex(hexbytes)
        if pe.read_va(va, len(want)) != want:
            raise PatchError("байты по адресу 0x%x другие: эта версия игры не поддерживается" % va,
                             "bytes at 0x%x differ: this build is not supported" % va)
    for va, name in IMPORT_NAMES:
        hint_rva = struct.unpack("<I", pe.read_va(va, 4))[0]
        if pe.read_cstr_va(IMAGE_BASE + hint_rva + 2) != name:
            raise PatchError("импорт по адресу 0x%x не %s" % (va, name.decode()),
                             "import at 0x%x is not %s" % (va, name.decode()))
    # Check 5 (changed, see README): the known builds carry data after the last section that no
    # section maps (zero padding and a 1028-byte block of 0xFF). It is kept byte for byte and the
    # new section is appended after it. Only a file cut short is refused.
    end = max(s.rawptr + s.rawsize for s in pe.sections)
    if len(pe.data) < end:
        raise PatchError("файл обрезан", "file is truncated")
    new_hdr_end = pe.sec_table + 40 * (pe.nsec + 1)
    if new_hdr_end > pe.size_of_headers:
        raise PatchError("нет места для заголовка новой секции",
                         "no room for one more section header")
    for s in pe.sections:
        if s.rawsize and new_hdr_end > s.rawptr:
            raise PatchError("нет места для заголовка новой секции",
                             "no room for one more section header")


# ---------------------------------------------------------------- caption, URL

def encode_caption(text):
    bad = sorted(set(ch for ch in text if ch not in GLYPHS))
    if bad:
        shown = "".join(bad)
        raise PatchError("в подписи есть символы, которых нет в шрифте игры: %s" % shown,
                         "caption has characters not in the game font: %s" % shown)
    try:
        raw = text.encode("cp1251")
    except UnicodeEncodeError:
        raise PatchError("подпись не кодируется в cp1251", "caption does not encode to cp1251")
    if not raw:
        raise PatchError("подпись пустая", "caption is empty")
    if len(raw) > 255:
        raise PatchError("подпись длиннее 255 байт", "caption is longer than 255 bytes")
    return raw


def encode_url(url):
    try:
        raw = url.encode("ascii")
    except UnicodeEncodeError:
        raise PatchError("адрес не ASCII", "URL is not ASCII")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise PatchError("адрес должен начинаться с http:// или https://",
                         "URL must start with http:// or https://")
    if len(raw) > 255:
        raise PatchError("адрес длиннее 255 байт", "URL is longer than 255 bytes")
    if any(b <= 0x20 or b >= 0x7F for b in raw):
        raise PatchError("в адресе пробелы или управляющие символы",
                         "URL contains spaces or control characters")
    return raw


# ---------------------------------------------------------------- PNG

def decode_png(data):
    """Return (width, height, rgb bytes) of a non-interlaced 8-bit RGB or RGBA PNG (RGBA on black)."""
    if data[:8] != PNG_SIGNATURE:
        raise PatchError("картинка не PNG", "image is not a PNG")
    pos = 8
    ihdr = None
    idat = []
    while True:
        if pos + 8 > len(data):
            raise PatchError("PNG обрезан", "PNG is truncated")
        length, ctype = struct.unpack_from(">I4s", data, pos)
        body_start = pos + 8
        body_end = body_start + length
        if body_end + 4 > len(data):
            raise PatchError("PNG обрезан", "PNG is truncated")
        body = data[body_start:body_end]
        crc = struct.unpack_from(">I", data, body_end)[0]
        if zlib.crc32(ctype + body) & MASK != crc:
            raise PatchError("ошибка CRC в PNG (%r)" % ctype, "PNG CRC error in chunk %r" % ctype)
        pos = body_end + 4
        if ctype == b"IHDR":
            ihdr = body
        elif ctype == b"IDAT":
            idat.append(body)
        elif ctype == b"IEND":
            break
    if ihdr is None or len(ihdr) < 13 or not idat:
        raise PatchError("в PNG нет IHDR или IDAT", "PNG has no IHDR or IDAT")
    width, height, depth, ctype, comp, filt, interlace = struct.unpack(">IIBBBBB", ihdr[:13])
    if width == 0 or height == 0:
        raise PatchError("пустая картинка", "empty image")
    if depth != 8 or ctype not in (2, 6):
        raise PatchError("поддерживаются PNG RGB и RGBA с глубиной 8 бит (найдено: depth %d, тип %d)" % (depth, ctype),
                         "only 8-bit RGB and RGBA PNG are supported (found depth %d, colour type %d)" % (depth, ctype))
    if comp != 0 or filt != 0 or interlace != 0:
        raise PatchError("чересстрочный или нестандартный PNG не поддерживается",
                         "interlaced or unusual PNG is not supported")
    try:
        raw = zlib.decompress(b"".join(idat))
    except zlib.error as e:
        raise PatchError("ошибка сжатия PNG: %s" % e, "PNG compression error: %s" % e)
    bpp = 3 if ctype == 2 else 4
    stride = width * bpp
    if len(raw) != height * (stride + 1):
        raise PatchError("размер данных PNG не сходится", "PNG pixel data has the wrong size")
    rows = []
    prev = bytearray(stride)
    for y in range(height):
        base = y * (stride + 1)
        f = raw[base]
        line = bytearray(raw[base + 1:base + 1 + stride])
        if f == 1:
            for i in range(bpp, stride):
                line[i] = (line[i] + line[i - bpp]) & 0xFF
        elif f == 2:
            for i in range(stride):
                line[i] = (line[i] + prev[i]) & 0xFF
        elif f == 3:
            for i in range(stride):
                left = line[i - bpp] if i >= bpp else 0
                line[i] = (line[i] + ((left + prev[i]) >> 1)) & 0xFF
        elif f == 4:
            for i in range(stride):
                a = line[i - bpp] if i >= bpp else 0
                b = prev[i]
                c = prev[i - bpp] if i >= bpp else 0
                p = a + b - c
                pa, pb, pc = abs(p - a), abs(p - b), abs(p - c)
                if pa <= pb and pa <= pc:
                    pred = a
                elif pb <= pc:
                    pred = b
                else:
                    pred = c
                line[i] = (line[i] + pred) & 0xFF
        elif f != 0:
            raise PatchError("неизвестный фильтр PNG %d" % f, "unknown PNG filter %d" % f)
        rows.append(line)
        prev = line
    out = bytearray(width * height * 3)
    o = 0
    for line in rows:
        if bpp == 3:
            out[o:o + stride] = line
            o += stride
        else:
            for x in range(0, stride, 4):
                a = line[x + 3]
                out[o] = (line[x] * a + 127) // 255
                out[o + 1] = (line[x + 1] * a + 127) // 255
                out[o + 2] = (line[x + 2] * a + 127) // 255
                o += 3
    return width, height, bytes(out)


# ---------------------------------------------------------------- pictures

def _box2(w, rgb, dw, dh):
    out = bytearray(dw * dh * 3)
    row = w * 3
    for y in range(dh):
        r0 = 2 * y * row
        r1 = r0 + row
        for x in range(dw):
            a = r0 + 6 * x
            b = r1 + 6 * x
            o = (y * dw + x) * 3
            for c in range(3):
                s = rgb[a + c] + rgb[a + 3 + c] + rgb[b + c] + rgb[b + 3 + c]
                out[o + c] = (s + 2) >> 2
    return bytes(out)


def _weights(d, scale, n):
    start = d * scale
    end = (d + 1) * scale
    res = []
    i = int(start)
    while i < end and i < n:
        lo = max(start, float(i))
        hi = min(end, float(i + 1))
        if hi > lo:
            res.append((i, (hi - lo) / scale))
        i += 1
    return res


def resize_rgb(w, h, rgb, dw, dh):
    """Exactly 2x: 2x2 box average. Otherwise area average (box filter)."""
    if (w, h) == (2 * dw, 2 * dh):
        return _box2(w, rgb, dw, dh)
    sx = w / float(dw)
    sy = h / float(dh)
    xw = [_weights(x, sx, w) for x in range(dw)]
    yw = [_weights(y, sy, h) for y in range(dh)]
    out = bytearray(dw * dh * 3)
    for dy in range(dh):
        for dx in range(dw):
            acc0 = acc1 = acc2 = 0.0
            for sy_i, wy in yw[dy]:
                for sx_i, wx in xw[dx]:
                    k = wx * wy
                    i = (sy_i * w + sx_i) * 3
                    acc0 += k * rgb[i]
                    acc1 += k * rgb[i + 1]
                    acc2 += k * rgb[i + 2]
            o = (dy * dw + dx) * 3
            for c, acc in enumerate((acc0, acc1, acc2)):
                out[o + c] = min(255, max(0, int(acc + 0.5)))
    return bytes(out)


def make_pictures(w, h, rgb, pw=None, ph=None):
    """Normal and lit pictures (pw*ph*3 bytes each). Ring 0 dark; lit rings 1-2 gold."""
    pw = PIC_W if pw is None else pw
    ph = PIC_H if ph is None else ph
    normal = bytearray(resize_rgb(w, h, rgb, pw, ph))
    for y in range(ph):
        for x in range(pw):
            if min(x, y, pw - 1 - x, ph - 1 - y) == 0:
                i = (y * pw + x) * 3
                normal[i:i + 3] = bytes(DARK)
    lit = bytearray(normal)
    for y in range(ph):
        for x in range(pw):
            if min(x, y, pw - 1 - x, ph - 1 - y) in (1, 2):
                i = (y * pw + x) * 3
                lit[i:i + 3] = bytes(GOLD)
    return bytes(normal), bytes(lit)


# ---------------------------------------------------------------- building

def build_section(base, content_len, caption_b, url_b, normal, lit):
    buf = bytearray(content_len)
    buf[0:len(CODE)] = CODE
    for off in FIX_ABS:
        v = struct.unpack_from("<I", buf, off)[0]
        struct.pack_into("<I", buf, off, (v + base) & MASK)
    for off in FIX_REL:
        v = struct.unpack_from("<I", buf, off)[0]
        struct.pack_into("<I", buf, off, (v - base) & MASK)
    buf[LAYOUT["OPEN"]:LAYOUT["OPEN"] + 5] = b"open\0"
    cap = LAYOUT["CAPTION"]
    buf[cap] = len(caption_b)
    buf[cap + 1:cap + 1 + len(caption_b)] = caption_b
    buf[LAYOUT["URL"]:LAYOUT["URL"] + len(url_b)] = url_b
    buf[LAYOUT["PIX_N"]:LAYOUT["PIX_N"] + len(normal)] = normal
    buf[LAYOUT["PIX_L"]:LAYOUT["PIX_L"] + len(lit)] = lit
    return bytes(buf)


def build_patched(exe, png, url, caption):
    """Return the patched EXE as bytes. Raises PatchError on any failed check."""
    url_b = encode_url(url)
    caption_b = encode_caption(caption)
    pe = Pe(exe)
    check_exe(pe)
    w, h, rgb = decode_png(png)
    normal, lit = make_pictures(w, h, rgb)
    content_len = LAYOUT["PIX_L"] + PIC_W * PIC_H * 3
    va = align_up(pe.size_of_image, pe.section_align)
    rawptr = align_up(len(exe), pe.file_align)
    rawsize = align_up(content_len, pe.file_align)
    base = IMAGE_BASE + va
    content = build_section(base, content_len, caption_b, url_b, normal, lit)

    out = bytearray(exe)
    out += b"\0" * (rawptr - len(exe))
    out += content
    out += b"\0" * (rawsize - content_len)

    off = pe.va_to_off(HOOK_BUILD, 6)
    rel = (base + ENTRY["build_hook"] - (HOOK_BUILD + 5)) & MASK
    out[off:off + 6] = b"\xe9" + struct.pack("<I", rel) + b"\x90"
    off = pe.va_to_off(HOOK_DRAW, 5)
    rel = (base + ENTRY["draw_hook"] - (HOOK_DRAW + 5)) & MASK
    out[off:off + 5] = b"\xe8" + struct.pack("<I", rel)

    hdr = pe.sec_table + 40 * pe.nsec
    out[hdr:hdr + 40] = struct.pack("<8sIIIIIIHHI", SECTION_NAME, content_len, va, rawsize, rawptr,
                                    0, 0, 0, 0, SECTION_FLAGS)
    struct.pack_into("<H", out, pe.nsec_off, pe.nsec + 1)
    struct.pack_into("<I", out, pe.size_of_image_off, align_up(va + content_len, pe.section_align))
    struct.pack_into("<I", out, pe.checksum_off, pe_checksum(out, pe.checksum_off))
    return bytes(out)


# ---------------------------------------------------------------- files and CLI

def _write_atomic(path, data):
    tmp = path.with_name(path.name + ".tmp")
    try:
        with open(str(tmp), "wb") as f:
            f.write(data)
        os.replace(str(tmp), str(path))
    except OSError as e:
        try:
            if tmp.exists():
                tmp.unlink()
        except OSError:
            pass
        raise PatchError("не удалось записать %s (игра запущена?): %s" % (path, e),
                         "could not write %s (is the game running?): %s" % (path, e))


def patch(exe_path, image_path=None, url=DEFAULT_URL, caption=DEFAULT_CAPTION, log=print):
    exe = Path(exe_path)
    bak = exe.with_name(exe.name + ".bak")
    if bak.exists():
        raise PatchError("есть %s: файл уже пропатчен, сначала запустите с --restore" % bak.name,
                         "%s exists: the file was patched before, run with --restore first" % bak.name)
    if not exe.is_file():
        raise PatchError("файл не найден: %s" % exe, "file not found: %s" % exe)
    image = Path(image_path) if image_path else HERE / "capsule.png"
    if not image.is_file():
        raise PatchError("картинка не найдена: %s" % image, "image not found: %s" % image)
    original = exe.read_bytes()
    patched = build_patched(original, image.read_bytes(), url, caption)
    log("Проверки пройдены / Checks passed")
    try:
        with open(str(bak), "xb") as f:
            f.write(original)
    except OSError as e:
        raise PatchError("не удалось создать %s: %s" % (bak.name, e),
                         "could not create %s: %s" % (bak.name, e))
    try:
        _write_atomic(exe, patched)
    except PatchError:
        bak.unlink()
        raise
    log("Резервная копия / Backup: %s" % bak)
    log("Готово / Done: %s (секция .banner добавлена / .banner section added)" % exe)


def restore(exe_path, log=print):
    exe = Path(exe_path)
    bak = exe.with_name(exe.name + ".bak")
    if not bak.is_file():
        raise PatchError("нет %s: нечего восстанавливать" % bak.name,
                         "%s not found: nothing to restore" % bak.name)
    _write_atomic(exe, bak.read_bytes())
    bak.unlink()
    log("Восстановлено / Restored: %s" % exe)


def main(argv=None):
    ap = argparse.ArgumentParser(
        description="Баннер Thorny Times в главном меню Discord Times. / "
                    "Thorny Times banner in the Discord Times main menu.")
    ap.add_argument("exe", nargs="?", default="DiscordTimes.exe", help="DiscordTimes.exe")
    ap.add_argument("--image", default=str(HERE / "capsule.png"), help="PNG picture (RGB or RGBA, 8 bit)")
    ap.add_argument("--url", default=DEFAULT_URL, help="link opened on click")
    ap.add_argument("--caption", default=DEFAULT_CAPTION, help="caption under the banner (cp1251 text)")
    ap.add_argument("--restore", action="store_true", help="put the original back from .bak")
    args = ap.parse_args(argv)
    try:
        if args.restore:
            restore(args.exe)
        else:
            patch(args.exe, args.image, args.url, args.caption)
    except PatchError as e:
        print("Ошибка / Error: %s" % e, file=sys.stderr)
        return 1
    except OSError as e:
        print("Ошибка / Error: %s" % e, file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(errors="replace")
        except (AttributeError, ValueError):
            pass
    sys.exit(main())
